:root {
  /* Colors */
  --color-paper-canvas: #ffffff;
  --color-mist-wash: #f3f5fc;
  --color-jet-ink: #262626;
  --color-graphite-body: #3e343f;
  --color-graphite-caption: #3e343f80;
  --color-fog-border: #ebebeb;
  --color-frosted-hairline: #ebebeb26;
  --color-signal-cobalt: #267dff;
  --color-mint-code: #00d085;
  --color-amethyst-code: #9867ff;
  --color-sunbeam-code: #f4e82f;
  --color-ember-banner: #dc2626;
  --color-steel-consent: #1863dc;

  /* Typography — Font Families */
  --font-epilogue: "Epilogue", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Typography — Scale */
  --text-small: 12px;
  --leading-small: 1.58;
  --tracking-small: 0px;
  --text-caption: 14px;
  --leading-caption: 1.43;
  --tracking-caption: 0px;
  --text-body-sm: 15px;
  --leading-body-sm: 1.33;
  --tracking-body-sm: 0px;
  --text-body: 16px;
  --leading-body: 1.5;
  --tracking-body: 0px;
  --text-body-lg: 20px;
  --leading-body-lg: 1.35;
  --tracking-body-lg: 0px;
  --text-subheading: 24px;
  --leading-subheading: 1.17;
  --tracking-subheading: -0.96px;
  --text-heading-sm: 32px;
  --leading-heading-sm: 1.03;
  --tracking-heading-sm: -1.28px;
  --text-heading: 40px;
  --leading-heading: 1.0;
  --tracking-heading: -1.6px;
  --text-heading-lg: 48px;
  --leading-heading-lg: 1.0;
  --tracking-heading-lg: -1.92px;
  --text-display: 64px;
  --leading-display: 1.04;
  --tracking-display: -2.56px;
  --tracking-button-label: -0.16px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-5: 5px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-30: 30px;
  --spacing-40: 40px;
  --spacing-45: 45px;
  --spacing-56: 56px;
  --spacing-60: 60px;
  --spacing-102: 102px;

  /* Layout */
  --layout-max-width: 1110px;
  --layout-section-gap: 102px;
  --layout-card-padding: 40px;
  --layout-element-gap: 30px;

  /* Border Radius */
  --radius-sm: 2px;
  --radius-md: 4px;
  --radius-lg: 6px;
  --radius-xl: 10px;
  --radius-2xl: 50px;
  --radius-full: 50%;

  /* Named Radii */
  --radius-cards: 10px;
  --radius-buttons: 10px;
  --radius-nav: 4px;
  --radius-tags: 4px;
  --radius-small-cards: 4px;
  --radius-images: 6px;
  --radius-inputs: 50px;
  --radius-avatars: 50%;
  --radius-small-elements: 2px;
  --radius-alert-banners: 0px;

  /* Shadows */
  --shadow-sm: rgb(152, 103, 255) 1px 1px 0px 2px;
  --shadow-md: rgba(172, 171, 171, 0.3) 0px -1px 10px 0px;
  --shadow-xl: rgba(0, 0, 0, 0.3) 0px 32px 68px 0px;

  /* Surfaces */
  --surface-paper-canvas: #ffffff;
  --surface-mist-wash: #f3f5fc;
  --surface-signal-cobalt: #267dff;
  --surface-ember-banner: #dc2626;
}

